package net.officefloor.hq.app.claim;

import java.util.List;
import java.util.Optional;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Modifying;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;

public interface ClaimRepository extends JpaRepository<Claim, Long> {

    /** The sheet's claims, newest listed first. */
    List<Claim> findBySheetIdOrderByListedDesc(String sheetId);

    /** A person's claims, newest listed first. */
    List<Claim> findBySheetIdAndPersonIdOrderByListedDesc(String sheetId, Long personId);

    /** A person's claim by its number on the sheet. */
    Optional<Claim> findBySheetIdAndPersonIdAndNumber(String sheetId, Long personId, String number);

    /** The numbers given on the sheet's claims. */
    @Query("select c.number from Claim c where c.sheetId = :sheetId and c.number is not null")
    List<String> numbers(@Param("sheetId") String sheetId);

    /** The numbers given up on the sheet by re-dated claims: never given again. */
    @Query(value = "SELECT claim_number FROM retired_claim_number WHERE sheet_id = :sheetId", nativeQuery = true)
    List<String> retiredNumbers(@Param("sheetId") String sheetId);

    /** Give up a claim number on the sheet for good. */
    @Modifying(flushAutomatically = true)
    @Query(value = "MERGE INTO retired_claim_number (sheet_id, claim_number) KEY (sheet_id, claim_number) VALUES (:sheetId, :number)",
            nativeQuery = true)
    void retireNumber(@Param("sheetId") String sheetId, @Param("number") String number);

    /** List a claim anew: it becomes the newest under its person. */
    @Modifying(flushAutomatically = true)
    @Query(value = "UPDATE claim SET listed = NEXT VALUE FOR claim_listed_seq WHERE id = :id", nativeQuery = true)
    void relist(@Param("id") Long id);

    /** Mark the claims as settled by a settle batch. */
    @Modifying(flushAutomatically = true, clearAutomatically = true)
    @Query("update Claim c set c.batch = :batch where c.id in :ids")
    void markBatch(@Param("ids") List<Long> ids, @Param("batch") Long batch);

    /** Release every editor's lock on the sheet's claims. */
    @Modifying(flushAutomatically = true)
    @Query("update Claim c set c.lockedBy = null where c.sheetId = :sheetId and c.lockedBy is not null")
    int releaseLocks(@Param("sheetId") String sheetId);

    /** Whether a claim on the sheet other than the given one (null: any) carries the reference key. */
    @Query("select count(c) > 0 from Claim c where c.sheetId = :sheetId and c.refKey = :refKey"
            + " and (:id is null or c.id <> :id)")
    boolean refInUse(@Param("sheetId") String sheetId, @Param("refKey") String refKey, @Param("id") Long id);

    /** Every tag ever used on the sheet's claims, sorted. */
    @Query(value = "SELECT tag FROM sheet_tag WHERE sheet_id = :sheetId ORDER BY tag", nativeQuery = true)
    List<String> tagsUsed(@Param("sheetId") String sheetId);

    /** Keep a tag on the sheet's list of the tags ever used. */
    @Modifying(flushAutomatically = true)
    @Query(value = "MERGE INTO sheet_tag (sheet_id, tag) KEY (sheet_id, tag) VALUES (:sheetId, :tag)",
            nativeQuery = true)
    void useTag(@Param("sheetId") String sheetId, @Param("tag") String tag);

    Optional<Claim> findByIdAndSheetIdAndPersonId(Long id, String sheetId, Long personId);
}
package net.officefloor.hq.app.claim;

import java.util.List;
import org.springframework.data.jpa.repository.JpaRepository;

public interface ClaimLogRepository extends JpaRepository<ClaimLogEntry, Long> {

    /** The sheet's status log lines, oldest first. */
    List<ClaimLogEntry> findBySheetIdOrderByIdAsc(String sheetId);

    /** A claim's status log lines, oldest first. */
    List<ClaimLogEntry> findByClaimIdOrderByIdAsc(Long claimId);
}
package net.officefloor.hq.app.claim;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.time.LocalDate;

/** One line of a claim's status log: a status it moved to, who moved it, the sheet's today when they
 *  did, and the claim's due as it was computed then (two decimals, or n/a when it had none). */
@Entity
@Table(name = "claim_status_log")
public class ClaimLogEntry {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false, updatable = false)
    private String sheetId;

    @Column(name = "claim_id", nullable = false, updatable = false)
    private Long claimId;

    @Enumerated(EnumType.STRING)
    @Column(name = "status", nullable = false, updatable = false)
    private ClaimStatus status;

    @Column(name = "changed_by", nullable = false, updatable = false)
    private String by;

    @Column(name = "changed_on", nullable = false, updatable = false)
    private LocalDate on;

    @Column(name = "due", nullable = false, updatable = false)
    private String due;

    protected ClaimLogEntry() {
    }

    public ClaimLogEntry(String sheetId, Long claimId, ClaimStatus status, String by, LocalDate on, String due) {
        this.sheetId = sheetId;
        this.claimId = claimId;
        this.status = status;
        this.by = by;
        this.on = on;
        this.due = due;
    }

    public Long getClaimId() {
        return claimId;
    }

    public ClaimStatus getStatus() {
        return status;
    }

    public LocalDate getOn() {
        return on;
    }

    /** The line as the claim shows it: <STATUS> by <user> on <date> due=<due>. */
    public String text() {
        return status + " by " + by + " on " + on + " due=" + due;
    }
}
-- What the sheet held as of a day: each change that bears on a claim's figures is kept with the
-- sheet's today when it was made, so a statement can be taken as of a past day (every change made
-- while the sheet's today was on or before it counts, every later one does not).

-- The sheet's today when the person was added; null for one added before this was kept.
ALTER TABLE person ADD COLUMN added_on DATE;

-- The sheet's today when the hold was put on; null for one put on before this was kept.
ALTER TABLE person_hold ADD COLUMN made_on DATE;

-- Each rate as it was set: the grade's rate from its from-date, as of the sheet's today then.
CREATE TABLE rate_history (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    grade VARCHAR(1) NOT NULL,
    from_date DATE,
    to_date DATE,
    rate DECIMAL(7, 2) NOT NULL,
    made_on DATE NOT NULL
);
CREATE INDEX rate_history_sheet ON rate_history (sheet_id, grade, id);

-- Each grade a person was given from a from-date, as of the sheet's today then.
CREATE TABLE person_grade_history (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    person_id BIGINT NOT NULL REFERENCES person (id),
    grade VARCHAR(1) NOT NULL,
    from_date DATE,
    made_on DATE NOT NULL
);
CREATE INDEX person_grade_history_person ON person_grade_history (person_id, id);

-- Each value recorded for a dated setting from a from-date, as of the sheet's today then.
CREATE TABLE sheet_setting_value_history (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    setting_key VARCHAR(40) NOT NULL,
    from_date DATE NOT NULL,
    setting_value DECIMAL(12, 2),
    made_on DATE NOT NULL
);
CREATE INDEX sheet_setting_value_history_key ON sheet_setting_value_history (sheet_id, setting_key, id);

-- Each policy date set (null: blank), as of the sheet's today then.
CREATE TABLE sheet_policy_date_history (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    policy_date DATE,
    made_on DATE NOT NULL
);
CREATE INDEX sheet_policy_date_history_sheet ON sheet_policy_date_history (sheet_id, id);

-- Each state a claim was saved in, as of the sheet's today then.
CREATE TABLE claim_history (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    claim_id BIGINT NOT NULL REFERENCES claim (id),
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    person_id BIGINT NOT NULL,
    amount DECIMAL(12, 2) NOT NULL,
    claim_date DATE NOT NULL,
    due_by DATE NOT NULL,
    status VARCHAR(20) NOT NULL,
    settled_due DECIMAL(12, 2),
    stated BOOLEAN NOT NULL,
    stated_due DECIMAL(12, 2),
    corrects_number VARCHAR(255),
    deferred_until DATE,
    made_on DATE NOT NULL
);
CREATE INDEX claim_history_claim ON claim_history (claim_id, id);
-- What the screen shows as of a day: every change kept with the sheet's today when it was made, so
-- the whole sheet can be read back as it stood at the end of a past day.

-- The rest of a claim's state, kept with each state it was saved in; complete is false on the rows
-- kept before these were (their values are read from the claim as it is now).
ALTER TABLE claim_history ADD COLUMN claim_number VARCHAR(255);
ALTER TABLE claim_history ADD COLUMN opened_by VARCHAR(200);
ALTER TABLE claim_history ADD COLUMN note VARCHAR(2000);
ALTER TABLE claim_history ADD COLUMN proofs INT;
ALTER TABLE claim_history ADD COLUMN split_from VARCHAR(255);
ALTER TABLE claim_history ADD COLUMN late_entry BOOLEAN;
ALTER TABLE claim_history ADD COLUMN complete BOOLEAN DEFAULT FALSE NOT NULL;

-- Each state a person was saved in (name, terms, retirement), as of the sheet's today then.
CREATE TABLE person_history (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    person_id BIGINT NOT NULL REFERENCES person (id),
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    name VARCHAR(200) NOT NULL,
    terms INT,
    retired_from DATE,
    made_on DATE NOT NULL
);
CREATE INDEX person_history_sheet ON person_history (sheet_id, person_id, id);

-- The sheet's today when the statement was taken (taken_on is the day it was taken as of); null
-- for one taken before this was kept.
ALTER TABLE statement ADD COLUMN made_on DATE;

-- The sheet's today when the patron was named; null for one named before this was kept.
ALTER TABLE person_patron ADD COLUMN made_on DATE;

-- Each time a user started or stopped watching a person, as of the sheet's today then.
CREATE TABLE person_watch_history (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    person_id BIGINT NOT NULL REFERENCES person (id),
    user_name VARCHAR(200) NOT NULL,
    watched BOOLEAN NOT NULL,
    made_on DATE NOT NULL
);
CREATE INDEX person_watch_history_sheet ON person_watch_history (sheet_id, user_name, id);

-- Each state a period was saved in, as of the sheet's today then; person_totals is each person's
-- fixed due-total as person-id=total pairs separated by commas (blank while it is open).
CREATE TABLE period_history (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    period_id BIGINT NOT NULL REFERENCES period (id),
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    name VARCHAR(200) NOT NULL,
    from_date DATE NOT NULL,
    to_date DATE NOT NULL,
    closed BOOLEAN NOT NULL,
    soft_closed BOOLEAN NOT NULL,
    closed_total DECIMAL(12, 2),
    person_totals VARCHAR(100000) NOT NULL,
    made_on DATE NOT NULL
);
CREATE INDEX period_history_sheet ON period_history (sheet_id, period_id, id);

-- Each value set for a sheet setting that is not dated (a role, a permission, the period numbering
-- from, the grace days), by key, as of the sheet's today then; null for blank.
CREATE TABLE sheet_setting_history (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    setting_key VARCHAR(300) NOT NULL,
    setting_value VARCHAR(500),
    made_on DATE NOT NULL
);
CREATE INDEX sheet_setting_history_key ON sheet_setting_history (sheet_id, setting_key, id);

-- The sheet's today when the steward role was delegated; null for one made before this was kept.
ALTER TABLE delegation ADD COLUMN made_on DATE;

