package net.officefloor.hq.app;

import java.time.LocalDate;

/** The as-of date a user's screen is set to: while it is set, everything the screen reads is as it
 *  stood at the end of that day and every change is refused. It belongs to the screen, which sends it
 *  in a header with each request; a request without it reads the sheet as it is now. */
public final class AsOf {

    /** The header carrying the screen's as-of date (yyyy-mm-dd). */
    public static final String HEADER = "X-As-Of";

    private AsOf() {
    }

    /** The as-of date a header carries; null when it is absent or blank (the screen shows now). */
    public static LocalDate parse(String header) {
        return header == null || header.isBlank() ? null : LocalDate.parse(header.trim());
    }
}
#!/usr/bin/env bash
# Start the Spring Boot app on $PORT (main class net.officefloor.hq.app.Application). On boot, Flyway
# migrates the empty in-memory H2 up to the current schema; Spring serves the SPA (static/) and the
# app's REST endpoints. Returns once
# launching; poll /actuator/health for readiness.
set -euo pipefail
cd "$(dirname "$0")/.."
mkdir -p .run

: "${PORT:?PORT must be set}"
JAR="$(ls -t target/*.jar 2>/dev/null | head -n1 || true)"
[ -n "$JAR" ] || { echo "no jar in target/ — run bin/build first" >&2; exit 1; }

# Known audit file (the file-based test-assertion channel). Absolute so app + tests agree.
export AUDIT_FILE="${AUDIT_FILE:-$PWD/.run/audit.log}"

nohup java -jar "$JAR" --server.port="$PORT" --spring.profiles.active=e2e > .run/app.log 2>&1 &
echo $! > .run/app.pid

